75	// Componente para redirecionar usuários logados da raiz
76	function HomeRedirect() {
77	  const navigate = useNavigate();
78	  const [checking, setChecking] = useState(true);
79	
80	  useEffect(() => {
81	    supabase.auth.getUser().then(({ data: { user } }) => {
82	      if (user) {
83	        const userType = user.user_metadata?.user_type;
84	        if (userType === 'hire') {
85	          navigate('/company/dashboard');
86	        } else {
87	          navigate('/dashboard');
88	        }
89	      }
90	      setChecking(false);
91	    });
92	  }, [navigate]);
93	
94	  if (checking) return <div className="h-screen flex items-center justify-center bg-[#F4F4F0] animate-pulse"><div className="h-12 w-32 bg-gray-200 rounded-xl" /></div>;
95	
96	  return <Onboarding />;
97	}
