99	import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
100	
101	// Create a client
102	const queryClient = new QueryClient({
103	  defaultOptions: {
104	    queries: {
105	      staleTime: 1000 * 60 * 5, // 5 minutes
106	      gcTime: 1000 * 60 * 30, // 30 minutes
107	      refetchOnWindowFocus: false,
