135	                    {/* Admin Route - protected, Admin.tsx checks email authorization */}
136	                    <Route path="/admin" element={<Admin />} />
137	
138	                    {/* Onboarding Routes - still protected as they need user session but not full layout yet if incomplete */}
139	                    <Route path="/company/onboarding" element={<CompanyOnboarding />} />
140	                    <Route path="/worker/onboarding" element={<WorkerOnboarding />} />
141	
142	                    {/* Worker Layout Routes */}
143	                    <Route path="/" element={<MainLayout />}>
144	                      <Route path="dashboard" element={<Dashboard />} />
145	                      <Route path="jobs" element={<Jobs />} />
146	                      <Route path="my-jobs" element={<MyJobs />} />
147	                      <Route path="analytics" element={<Analytics />} />
148	                      <Route path="wallet" element={<Wallet />} />
149	                      <Route path="profile" element={<Profile />} />
150	                      <Route path="messages" element={<Messages />} />
151	                      <Route path="notifications" element={<Notifications />} />
152	                      <Route path="worker/dashboard" element={<WorkerDashboard />} />
153	                    </Route>
154	
155	                    {/* Company Layout Routes */}
156	                    <Route path="/company" element={<CompanyLayout />}>
157	                      <Route path="dashboard" element={<CompanyDashboard />} />
158	                      <Route path="create" element={<CompanyCreateJob />} />
159	                      <Route path="jobs" element={<CompanyJobs />} />
160	                      <Route path="jobs/:id" element={<CompanyJobDetails />} />
161	                      <Route path="jobs/:id/edit" element={<CompanyCreateJob />} />
162	                      <Route path="jobs/:id/candidates" element={<CompanyJobCandidates />} />
163	                      <Route path="worker/:id" element={<WorkerPublicProfile />} />
164	                      <Route path="profile" element={<CompanyProfile />} />
165	                      <Route path="messages" element={<CompanyMessages />} />
166	                      <Route path="wallet" element={<CompanyWallet />} />
167	                      <Route path="analytics" element={<CompanyAnalytics />} />
168	                      <Route path="team" element={<CompanyTeam />} />
169	                      <Route path="notifications" element={<Notifications />} />
170	                    </Route>
171	
172	                  </Route>
173	                  <Route path="*" element={<NotFound />} />
174	                </Routes>
175	              </Suspense>
176	            </BrowserRouter>
177	          </ToastProvider>
178	        </NotificationProvider>
179	      </AuthProvider>
180	    </QueryClientProvider>
181	    </ErrorBoundary>
182	  );
183	}
184	
185	export default App;
