2	import { useEffect, useState, useCallback } from 'react';
3	import { supabase } from '../lib/supabase';
4	import { MapPin, CheckCircle2, Clock, XCircle, Loader2, DollarSign, Star, Play, Square, AlertCircle, Bell, Building2 } from 'lucide-react';
5	import PageMeta from '../components/PageMeta';
6	import { useNavigate } from 'react-router-dom';
7	import { formatDistanceToNow, isToday, parseISO, isWithinInterval, setHours, setMinutes } from 'date-fns';
8	import { ptBR } from 'date-fns/locale';
9	import RateModal from '../components/RateModal';
10	import JobLifecycleStepper from '../components/JobLifecycleStepper';
11	import { useToast } from '../contexts/ToastContext';
12	import { logError } from '../lib/logger';
13	import { useWorkerInvites } from '../hooks/useShiftInvites';
14	import type { ReviewDirection } from '../types';
15	
16	type Step = { label: string; status: 'complete' | 'active' | 'pending' }
17	
18	function computeWorkerSteps(job: JobApplication): Step[] {
19	    const checkinDone = !!job.worker_checkin_at;
20	    const checkoutDone = !!job.worker_checkout_at;
21	    const companyConfirmed = !!job.company_checkout_confirmed_at;
22	
23	    return [
24	        {
25	            label: 'Chegada registrada',
26	            status: checkinDone ? 'complete' : 'active'
27	        },
28	        {
29	            label: 'Check-out',
30	            status: checkoutDone
31	                ? 'complete'
32	                : checkinDone && !checkoutDone
33	                    ? 'active'
34	                    : 'pending'
35	        },
36	        {
37	            label: 'Aguardando empresa',
38	            status: companyConfirmed
39	                ? 'complete'
40	                : checkoutDone && !companyConfirmed
41	                    ? 'active'
42	                    : 'pending'
43	        }
44	    ];
45	}
46	
47	interface JobApplication {
48	    id: string;
49	    job_id: string;
50	    status: string;
51	    title: string;
52	    company_id: string;
53	    company_name: string;
54	    company_logo: string | null;
55	    pay: number;
56	    date: string;
57	    raw_date: string | null;
58	    time: string;
59	    end_time: string | null;
60	    location: string;
61	    month: string;
62	    day: number | string;
63	    worker_checkin_at: string | null;
64	    worker_checkout_at: string | null;
65	    company_checkin_confirmed_at: string | null;
66	    company_checkout_confirmed_at: string | null;
67	}
68	
69	type ActiveTab = 'invites' | 'applied' | 'in_progress' | 'scheduled' | 'history';
70	
71	export default function MyJobs() {
72	    const navigate = useNavigate();
73	    const [loading, setLoading] = useState(true);
74	    const [activeTab, setActiveTab] = useState<ActiveTab>('invites');
75	    const [jobs, setJobs] = useState<{
76	        applied: JobApplication[],
77	        in_progress: JobApplication[],
78	        scheduled: JobApplication[],
79	        history: JobApplication[]
80	    }>({ applied: [], in_progress: [], scheduled: [], history: [] });
81	
82	    // Rating State
83	    const [rateModalOpen, setRateModalOpen] = useState(false);
84	    const [selectedJobToRate, setSelectedJobToRate] = useState<JobApplication | null>(null);
85	    const [reviewedJobIds, setReviewedJobIds] = useState<Set<string>>(new Set());
86	    const [actionLoading, setActionLoading] = useState<string | null>(null);
87	    const [confirmCancelId, setConfirmCancelId] = useState<string | null>(null);
88	    const { addToast } = useToast();
89	
90	    // Hook de convites push
91	    const { pendingInvites, loading: invitesLoading, respondingId, respond } = useWorkerInvites();
92	
93	    const fetchJobs = useCallback(async () => {
94	        const { data: { user } } = await supabase.auth.getUser();
95	        if (!user) return navigate('/login');
96	
97	        // Fetch my reviews to know what I've rated
98	        const { data: myReviews } = await supabase
99	            .from('reviews')
100	            .select('job_id')
101	            .eq('reviewer_id', user.id);
102	
103	        const reviewedSet = new Set(myReviews?.map(r => r.job_id) || []);
104	        setReviewedJobIds(reviewedSet);
105	
106	        const { data, error } = await supabase
107	            .from('applications')
108	            .select(`
109	                id,
110	                status,
111	                created_at,
112	                worker_checkin_at,
113	                worker_checkout_at,
114	                company_checkin_confirmed_at,
115	                company_checkout_confirmed_at,
116	                job:jobs (
117	                    id,
118	                    title,
119	                    budget,
120	                    start_date,
121	                    work_start_time,
122	                    work_end_time,
123	                    location,
124	                    company:companies (
125	                        id,
126	                        name,
127	                        logo_url
128	                    )
129	                )
130	            `)
131	            .eq('worker_id', user.id)
132	            // Excluir convites pending — eles ficam na aba Convites via hook
133	            .not('status', 'eq', 'invited')
134	            .order('created_at', { ascending: false });
135	
136	        if (error) {
137	            logError('Error fetching applications:', error);
138	        } else {
139	            const applied: JobApplication[] = [];
140	            const in_progress: JobApplication[] = [];
141	            const scheduled: JobApplication[] = [];
142	            const history: JobApplication[] = [];
143	
144	            const now = new Date();
145	
146	            interface ApplicationRow {
147	                id: string;
148	                status: string;
149	                created_at: string;
150	                worker_checkin_at: string | null;
151	                worker_checkout_at: string | null;
152	                company_checkin_confirmed_at: string | null;
153	                company_checkout_confirmed_at: string | null;
154	                job: {
155	                    id: string;
156	                    title: string;
157	                    budget: number;
158	                    start_date: string | null;
159	                    work_start_time: string | null;
160	                    work_end_time: string | null;
161	                    location: string | null;
162	                    company: {
163	                        id: string;
164	                        name: string;
165	                        logo_url: string | null;
166	                    } | null;
167	                } | null;
168	            }
169	
170	            (data as unknown as ApplicationRow[]).forEach((app) => {
171	                const application: JobApplication = {
172	                    id: app.id,
173	                    job_id: app.job?.id || '',
174	                    status: app.status,
175	                    title: app.job?.title || 'Job Desconhecido',
176	                    company_id: app.job?.company?.id || '',
177	                    company_name: app.job?.company?.name || 'Empresa Confidencial',
178	                    company_logo: app.job?.company?.logo_url ?? null,
179	                    pay: app.job?.budget || 0,
180	                    date: app.job?.start_date ? new Date(app.job.start_date).toLocaleDateString('pt-BR') : 'Data a definir',
181	                    raw_date: app.job?.start_date ?? null,
182	                    time: app.job?.work_start_time || 'Horário a definir',
183	                    end_time: app.job?.work_end_time || null,
184	                    location: app.job?.location || 'Local a definir',
185	                    month: app.job?.start_date ? new Date(app.job.start_date).toLocaleString('pt-BR', { month: 'short' }).toUpperCase().replace('.', '') : 'MES',
186	                    day: app.job?.start_date ? new Date(app.job.start_date).getDate() : '00',
187	                    worker_checkin_at: app.worker_checkin_at,
188	                    worker_checkout_at: app.worker_checkout_at,
189	                    company_checkin_confirmed_at: app.company_checkin_confirmed_at,
190	                    company_checkout_confirmed_at: app.company_checkout_confirmed_at
191	                };
192	
193	                const isJobToday = application.raw_date && isToday(parseISO(application.raw_date));
194	                let isWithinWorkHours = false;
195	
196	                if (isJobToday && application.time && application.end_time) {
197	                    try {
198	                        const [startH, startM] = application.time.split(':').map(Number);
199	                        const [endH, endM] = application.end_time.split(':').map(Number);
200	
201	                        const todayDate = new Date();
202	                        const startTime = setMinutes(setHours(todayDate, startH), startM);
203	                        let endTime = setMinutes(setHours(todayDate, endH), endM);
204	
205	                        if (endTime.getTime() <= startTime.getTime()) {
206	                            endTime = new Date(endTime.getTime() + 24 * 60 * 60 * 1000);
207	                        }
208	
209	                        const startBuffer = new Date(startTime.getTime() - 30 * 60 * 1000);
210	                        const endBuffer = new Date(endTime.getTime() + 60 * 60 * 1000);
211	
212	                        isWithinWorkHours = isWithinInterval(now, { start: startBuffer, end: endBuffer });
213	                    } catch (e) {
214	                        logError('Error parsing work hours:', e);
215	                    }
216	                }
217	
218	                const isInProgress = (app.status === 'hired' && isJobToday && isWithinWorkHours) || app.status === 'in_progress';
219	
220	                if (app.status === 'pending' || app.status === 'reviewing' || app.status === 'interview') {
221	                    applied.push(application);
222	                } else if (isInProgress) {
223	                    in_progress.push(application);
224	                } else if (app.status === 'hired') {
225	                    scheduled.push(application);
226	                } else if (['completed', 'rejected', 'cancelled', 'declined'].includes(app.status)) {
227	                    history.push(application);
228	                }
229	            });
230	
231	            setJobs({ applied, in_progress, scheduled, history });
232	        }
233	        setLoading(false);
234	    }, [navigate]);
235	
236	    useEffect(() => {
237	        fetchJobs();
238	    }, [fetchJobs]);
239	
240	    const handleCancelApplication = async (appId: string) => {
241	        setActionLoading(appId);
242	        try {
243	            const { error } = await supabase
244	                .from('applications')
245	                .update({ status: 'cancelled' })
246	                .eq('id', appId);
247	
248	            if (error) throw error;
249	            addToast('Candidatura cancelada.', 'success');
250	            await fetchJobs();
251	        } catch (err) {
252	            logError('Error cancelling application:', err);
253	            addToast('Erro ao cancelar candidatura. Tente novamente.', 'error');
254	        } finally {
255	            setActionLoading(null);
256	        }
257	    };
258	
259	    const handleCheckin = async (appId: string) => {
260	        setActionLoading(appId);
261	        try {
262	            const { error } = await supabase
263	                .from('applications')
264	                .update({
265	                    worker_checkin_at: new Date().toISOString(),
266	                    status: 'in_progress'
267	                })
268	                .eq('id', appId);
269	
270	            if (error) throw error;
271	            await fetchJobs();
272	        } catch (err) {
273	            logError('Error checking in:', err);
274	            addToast('Erro ao fazer check-in. Tente novamente.', 'error');
275	        } finally {
276	            setActionLoading(null);
277	        }
278	    };
279	
280	    const handleCheckout = async (appId: string) => {
281	        setActionLoading(appId);
282	        try {
283	            const { error } = await supabase
284	                .from('applications')
285	                .update({ worker_checkout_at: new Date().toISOString() })
286	                .eq('id', appId);
287	
288	            if (error) throw error;
289	            await fetchJobs();
290	        } catch (err) {
291	            logError('Error checking out:', err);
292	            addToast('Erro ao fazer check-out. Tente novamente.', 'error');
293	        } finally {
294	            setActionLoading(null);
295	        }
296	    };
297	
298	    const handleOpenRateModal = (job: JobApplication) => {
299	        setSelectedJobToRate(job);
300	        setRateModalOpen(true);
301	    };
302	
303	    // Fix R10: direction explícito ('company' quando worker avalia empresa)
304	    const handleSubmitRate = async (rating: number, comment: string) => {
305	        if (!selectedJobToRate) return;
306	
307	        try {
308	            const { data: { user } } = await supabase.auth.getUser();
309	            if (!user) throw new Error('Not authenticated');
310	
311	            const direction: ReviewDirection = 'company';
312	
313	            const { error } = await supabase.from('reviews').insert({
314	                job_id: selectedJobToRate.job_id,
315	                reviewer_id: user.id,
316	                reviewed_id: selectedJobToRate.company_id, // empresa sendo avaliada
317	                direction,
318	                rating,
319	                comment
320	            });
321	
322	            if (error) throw error;
323	
324	            setReviewedJobIds(prev => new Set(prev).add(selectedJobToRate.job_id));
325	            addToast('Avaliação enviada com sucesso!', 'success');
326	        } catch (error) {
327	            logError('Error submitting review:', error);
328	            addToast('Erro ao enviar avaliação.', 'error');
329	            throw error;
330	        }
331	    };
332	
333	    if (loading) return (
334	        <div className="flex flex-col gap-6 pb-24 max-w-4xl mx-auto animate-pulse">
335	            <div className="h-10 bg-gray-200 rounded w-1/3" />
336	            <div className="flex gap-2">
337	                {[...Array(5)].map((_, i) => <div key={i} className="h-10 bg-gray-200 rounded-xl w-24" />)}
338	            </div>
339	            <div className="space-y-4">
340	                {[...Array(4)].map((_, i) => (
341	                    <div key={i} className="h-28 bg-gray-200 rounded-2xl" />
342	                ))}
343	            </div>
344	        </div>
345	    );
346	
347	    return (
348	        <div className="flex flex-col gap-6 pb-24 font-sans text-accent max-w-4xl mx-auto">
349	            <PageMeta title="Meus Jobs" description="Acompanhe suas candidaturas, trabalhos agendados e histórico na Worki." />
350	
351	            <header>
352	                <h2 className="text-4xl font-black uppercase tracking-tighter">Meus Jobs</h2>
353	            </header>
354	
355	            {/* Tabs — Convites PRIMEIRO */}
356	            <div className="flex gap-2 border-b-2 border-gray-200 pb-1 overflow-x-auto scrollbar-hide">
357	                {[
358	                    { id: 'invites' as ActiveTab, label: 'Convites', count: pendingInvites.length, urgent: true },
359	                    { id: 'applied' as ActiveTab, label: 'Candidaturas', count: jobs.applied.length },
360	                    { id: 'in_progress' as ActiveTab, label: 'Em Andamento', count: jobs.in_progress.length },
361	                    { id: 'scheduled' as ActiveTab, label: 'Agendados', count: jobs.scheduled.length },
362	                    { id: 'history' as ActiveTab, label: 'Histórico', count: jobs.history.length }
363	                ].map((tab) => (
364	                    <button
365	                        key={tab.id}
366	                        onClick={() => setActiveTab(tab.id)}
367	                        className={`
368	                            px-6 py-2 rounded-t-xl font-bold uppercase transition-all whitespace-nowrap flex items-center gap-2
369	                            ${activeTab === tab.id
370	                                ? 'bg-black text-white translate-y-[2px]'
371	                                : 'text-gray-400 hover:text-black hover:bg-gray-100'}
372	                        `}
373	                    >
374	                        {tab.label}
375	                        {tab.count > 0 && (
376	                            <span className={`text-xs px-1.5 py-0.5 rounded-full font-black ${
377	                                tab.urgent
378	                                    ? 'bg-primary text-white animate-pulse'
379	                                    : tab.id === 'in_progress'
380	                                        ? 'bg-red-500 text-white animate-pulse'
381	                                        : 'bg-gray-200 text-gray-700'
382	                            }`}>
383	                                {tab.count}
384	                            </span>
385	                        )}
386	                    </button>
387	                ))}
388	            </div>
