168	      opts: { expiresInHours?: number; message?: string } = {},
169	    ): Promise<boolean> => {
170	      setInvitingWorkerId(workerId);
171	      const result = await ShiftInviteService.inviteWorkerToShift(jobId, workerId, opts);
172	      setInvitingWorkerId(null);
173	
174	      if (result.alreadyInvited) {
175	        addToast('Este freela já foi convidado para este turno.', 'info');
176	        return true;
177	      }
178	      if (result.error) {
179	        addToast(result.error, 'error');
180	        return false;
181	      }
182	
183	      addToast('Convite enviado com sucesso!', 'success');
184	      load();
185	      return true;
186	    },
187	    [jobId, addToast, load],
188	  );
189	
190	  return { invites, loading, invitingWorkerId, invite, refresh: load };
191	}
